-- SYS0010 buttons (4)
MERGE INTO SCM_ADM_MNU_BTN_MPG_M t USING (SELECT 'SYS0010' MNU_ID, 'lookupDetail' SHT_NM, 'SAVE' MNU_BTN_CD FROM DUAL) s
   ON (t.MNU_ID=s.MNU_ID AND t.SHT_NM=s.SHT_NM AND t.MNU_BTN_CD=s.MNU_BTN_CD)
 WHEN MATCHED THEN UPDATE SET API_ID='SYS0010_SAVE_LOOKUP_MASTER_DETAIL', USE_YN='Y', LAST_UPDATED_BY='admin', LAST_UPDATE_DATE=SYSDATE
 WHEN NOT MATCHED THEN INSERT (MNU_ID, SHT_NM, MNU_BTN_CD, API_ID, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
   VALUES ('SYS0010','lookupDetail','SAVE','SYS0010_SAVE_LOOKUP_MASTER_DETAIL','Y','admin',SYSDATE,'admin',SYSDATE);
